insert into platform_modules(code,title,is_active) values ('31-loan-legal-cases','پرونده‌های حقوقی مطالبات تسهیلات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('case-code','کد پرونده','text',true,10,'{}'),('contract-code','کد قرارداد','text',true,20,'{}'),('borrower-id','شناسه بدهکار','text',true,30,'{}'),('delinquency-code','کد معوقه','text',false,40,'{}'),('referral-date','تاریخ ارجاع','date',true,50,'{}'),('legal-type','نوع پرونده','select',true,60,'{"options":["مطالبه وجه","اجرای وثیقه","مطالبه از ضامن","چک و سفته","اعتراض به تعهد","سایر"]}'),('claim-amount','مبلغ مطالبه','number',true,70,'{}'),('paid-amount','مبلغ وصول‌شده','number',false,80,'{}'),('remaining-amount','مانده مطالبه','number',false,90,'{}'),('legal-unit','واحد حقوقی','text',false,100,'{}'),('lawyer','نماینده حقوقی','text',false,110,'{}'),('court-reference','مرجع قضایی','text',false,120,'{}'),('case-number','شماره پرونده قضایی','text',false,130,'{}'),('court-date','تاریخ رسیدگی','date',false,140,'{}'),('guarantee-action','اقدام نسبت به وثیقه','select',false,150,'{"options":["بدون اقدام","درخواست اجرا","مزایده","توقیف","آزادسازی","سایر"]}'),('case-status','وضعیت پرونده','select',true,160,'{"options":["ارجاع اولیه","در حال بررسی حقوقی","ثبت قضایی","در حال رسیدگی","اجرای حکم","توافق و سازش","وصول شده","مختومه","منصرف شده"]}'),('next-action-date','تاریخ اقدام بعدی','date',false,170,'{}'),('last-action','آخرین اقدام','textarea',false,180,'{}'),('resolution-reference','مرجع نتیجه','text',false,190,'{}'),('notes','یادداشت','textarea',false,200,'{}')
) v(k,t,ft,r,s,o) where m.code='31-loan-legal-cases' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values ('read','مشاهده','modules:31-loan-legal-cases:read'),('write','ثبت و ویرایش','modules:31-loan-legal-cases:write'),('delete','حذف','modules:31-loan-legal-cases:delete'),('refer','ارجاع حقوقی','modules:31-loan-legal-cases:refer'),('update','ثبت اقدام','modules:31-loan-legal-cases:update'),('settle','ثبت سازش','modules:31-loan-legal-cases:settle'),('close','مختومه کردن','modules:31-loan-legal-cases:close')) v(a,t,p) where m.code='31-loan-legal-cases' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;